"""Structural and evidence tests for app/engine/plan/metric_catalog.yaml (M05 section 3.1).

The catalog is Shekar-owned. Nothing here edits it; the tests pin its invariants:

* every tag exists in the real XBRL tag table (evidence regenerated by
  `uv run python tests/fixtures/make_catalog_tag_evidence.py` from `warehouse/raw/fsds_tag`),
  which is how an invented tag is caught;
* formulas resolve, do not cycle, and keep units and period types consistent;
* ADR-042 rules: a fallback needs `only_if`; a `presentation_basis` metric is its own concept and
  never shares a tag with, or feeds, another metric;
* the catalog is exactly the metric enum the planner schema exposes, and it has 25 metrics.
"""

from __future__ import annotations

import ast
import json
import re
from collections import Counter
from pathlib import Path

import pytest
import yaml

from app.engine.plan.catalog import (
    CATALOG_PATH,
    FALLBACK_CONDITIONS,
    MetricDef,
    formula_refs,
    load_catalog,
)
from app.engine.plan.schema import METRIC_NAMES

EVIDENCE_PATH = Path(__file__).resolve().parents[2] / "fixtures" / "catalog_tags_in_fsds.json"
EXPECTED_METRIC_COUNT = 25  # Shekar decided not to expand; change it consciously, with this test.
REGENERATE = "uv run python tests/fixtures/make_catalog_tag_evidence.py"

Catalog = dict[str, MetricDef]


# --- helpers (take a catalog so the meta-tests can feed them broken ones) ------------------------


def all_tags(catalog: Catalog) -> set[str]:
    return {tag for m in catalog.values() for tag in (m.tags or [])}


def expressions(m: MetricDef) -> list[str]:
    return [e for e in (m.formula, m.fallback_formula) if e is not None]


def formula_graph(catalog: Catalog) -> dict[str, set[str]]:
    return {
        name: {ref for expr in expressions(m) for ref in formula_refs(expr)}
        for name, m in catalog.items()
    }


def find_cycle(graph: dict[str, set[str]]) -> list[str] | None:
    """A cycle as a list of keys (first == last), or None. Iterative DFS with colours."""
    white, grey, black = 0, 1, 2
    colour = dict.fromkeys(graph, white)
    for start in graph:
        if colour[start] != white:
            continue
        stack: list[tuple[str, list[str]]] = [(start, sorted(graph[start]))]
        path = [start]
        colour[start] = grey
        while stack:
            node, todo = stack[-1]
            if not todo:
                colour[node] = black
                stack.pop()
                path.pop()
                continue
            nxt = todo.pop()
            if nxt not in graph:
                continue  # unknown ref: reported by the resolution test, not a cycle
            if colour[nxt] == grey:
                return [*path[path.index(nxt) :], nxt]
            if colour[nxt] == white:
                colour[nxt] = grey
                path.append(nxt)
                stack.append((nxt, sorted(graph[nxt])))
    return None


def leaf_tags(catalog: Catalog, name: str, _seen: frozenset[str] = frozenset()) -> set[str]:
    """Every tag a metric can read, following formula and fallback_formula references."""
    if name in _seen:
        return set()
    m = catalog[name]
    out = set(m.tags or [])
    for expr in expressions(m):
        for ref in formula_refs(expr):
            out |= leaf_tags(catalog, ref, _seen | {name})
    return out


def infer_unit(node: ast.expr, catalog: Catalog) -> str:
    """Unit of an arithmetic expression over catalog keys; raises AssertionError on a mix such as
    USD + shares. Numbers are 'scalar'."""
    if isinstance(node, ast.Constant):
        return "scalar"
    if isinstance(node, ast.Name):
        return catalog[node.id].unit
    if isinstance(node, ast.UnaryOp):
        return infer_unit(node.operand, catalog)
    assert isinstance(node, ast.BinOp), f"unexpected node {type(node).__name__}"
    left, right = infer_unit(node.left, catalog), infer_unit(node.right, catalog)
    if isinstance(node.op, ast.Add | ast.Sub):
        assert left == right, f"adding/subtracting {left} and {right}"
        return left
    if isinstance(node.op, ast.Mult):
        if left == "scalar":
            return right
        assert right == "scalar", f"multiplying {left} by {right}: no such unit in the catalog"
        return left
    assert isinstance(node.op, ast.Div)
    if right == "scalar":
        return left
    assert left == right, f"dividing {left} by {right}: no ratio unit for that"
    return "ratio"


def input_period_types(expr: str, catalog: Catalog) -> set[str | None]:
    return {catalog[ref].period_type for ref in formula_refs(expr)}


def load_evidence() -> dict[str, dict[str, object]]:
    assert EVIDENCE_PATH.exists(), f"missing {EVIDENCE_PATH.name}; run: {REGENERATE}"
    data = json.loads(EVIDENCE_PATH.read_text())
    tags = data["tags"]
    assert isinstance(tags, dict)
    return tags


@pytest.fixture(scope="module")
def catalog() -> Catalog:
    return load_catalog()


# --- loading and shape -----------------------------------------------------------------------


def test_catalog_loads_through_load_catalog(catalog: Catalog) -> None:
    """The yaml validates against MetricDef (extra keys forbidden, exactly one of tags/formula,
    formula operators limited) and every metric is a MetricDef."""
    assert catalog
    assert all(isinstance(m, MetricDef) for m in catalog.values())


def test_catalog_has_exactly_25_metrics(catalog: Catalog) -> None:
    """Shekar decided not to expand the catalog (the runbook said about 50). The count is pinned
    so that adding or removing a metric is a conscious edit of this test, which also reminds the
    author to review the tag chain, the numeric gold allowlist and the planner prompt."""
    assert len(catalog) == EXPECTED_METRIC_COUNT


def test_catalog_yaml_has_no_duplicate_top_level_keys() -> None:
    """yaml.safe_load silently keeps the LAST of two equal keys, so a pasted duplicate would
    silently replace a reviewed metric (and the count test would still say 25)."""

    class UniqueKeyLoader(yaml.SafeLoader):
        pass

    def construct(loader: UniqueKeyLoader, node: yaml.MappingNode, deep: bool = False) -> object:
        keys = [loader.construct_object(k, deep=deep) for k, _ in node.value]
        dupes = [k for k, n in Counter(keys).items() if n > 1]
        assert not dupes, f"duplicate yaml keys: {dupes}"
        return yaml.SafeLoader.construct_mapping(loader, node, deep=deep)

    UniqueKeyLoader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, construct)
    raw = yaml.load(CATALOG_PATH.read_text(), Loader=UniqueKeyLoader)  # noqa: S506
    assert len(raw) == EXPECTED_METRIC_COUNT


def test_catalog_keys_equal_planner_metric_enum(catalog: Catalog) -> None:
    """The planner's `metrics` enum is generated from the catalog, in catalog order; the model
    can only name metrics that exist. If the two drift, the structured-output schema lies."""
    assert tuple(catalog) == METRIC_NAMES
    assert set(catalog) == set(METRIC_NAMES)


def test_metric_keys_are_snake_case_and_labelled(catalog: Catalog) -> None:
    """Keys are lowercase snake_case identifiers (they appear in formulas, plans and gold files),
    and every metric has a non-empty label for the planner prompt."""
    for name, m in catalog.items():
        assert re.fullmatch(r"[a-z][a-z0-9_]*", name), name
        assert m.label and m.label.strip(), f"{name} has no label"


def test_synonyms_are_not_ambiguous_between_metrics(catalog: Catalog) -> None:
    """A synonym (or a label) that maps to two metrics makes the planner's choice arbitrary.
    Compared case-insensitively across all metrics."""
    owners: dict[str, set[str]] = {}
    for name, m in catalog.items():
        for word in [*m.synonyms, m.label or ""]:
            owners.setdefault(word.strip().lower(), set()).add(name)
    clashes = {w: sorted(o) for w, o in owners.items() if w and len(o) > 1}
    assert not clashes, f"ambiguous synonyms: {clashes}"


# --- tags exist in the real taxonomy ---------------------------------------------------------


def test_tags_are_bare_xbrl_names(catalog: Catalog) -> None:
    """fsds_tag stores bare element names (`Revenues`, not `us-gaap:Revenues`); a prefixed or
    misspelled-with-punctuation tag could never match a fact row."""
    for tag in all_tags(catalog):
        assert re.fullmatch(r"[A-Z][A-Za-z0-9]+", tag), f"suspicious tag {tag!r}"


def test_every_catalog_tag_exists_in_fsds_tag(catalog: Catalog) -> None:
    """M05 section 3.1: every listed tag exists in raw.fsds_tag. This is what catches an
    invented tag, which would otherwise compile into a query that silently returns nothing.

    Evidence comes from the local table (see make_catalog_tag_evidence.py). 'Exists' means a
    STANDARD element: a us-gaap row with custom = 0. A name that only appears as a company
    extension (custom = 1) is not the concept the catalog means."""
    evidence = load_evidence()
    problems = []
    for tag in sorted(all_tags(catalog)):
        entry = evidence.get(tag)
        if entry is None:
            problems.append(f"{tag}: not in the evidence file (regenerate: {REGENERATE})")
            continue
        if not entry["exists"]:
            problems.append(f"{tag}: not found in raw.fsds_tag (invented?)")
        elif 0 not in entry["custom_values"]:  # type: ignore[operator]
            problems.append(f"{tag}: only seen as a company-custom element")
        elif "us-gaap" not in entry["taxonomies"]:  # type: ignore[operator]
            problems.append(f"{tag}: never seen in the us-gaap taxonomy")
    assert not problems, "\n".join(problems)


def test_evidence_covers_exactly_the_catalog_tags(catalog: Catalog) -> None:
    """The evidence file lists the catalog's tags and nothing else. A tag added to the catalog
    without regenerating the file fails here (stale evidence is not evidence); a tag removed
    from the catalog leaves an orphan entry that also fails."""
    evidence = load_evidence()
    wanted = all_tags(catalog)
    assert set(evidence) == wanted, (
        f"missing from evidence: {sorted(wanted - set(evidence))}; "
        f"orphaned in evidence: {sorted(set(evidence) - wanted)}; regenerate: {REGENERATE}"
    )


def test_evidence_file_is_internally_consistent() -> None:
    """Each entry's `exists` agrees with its recorded versions/custom values, and its taxonomies
    are the prefixes of its versions, so a hand-edited 'exists: true' cannot pass unnoticed."""
    for tag, entry in load_evidence().items():
        versions = entry["versions"]
        assert isinstance(versions, list)
        assert entry["exists"] == bool(versions), tag
        assert entry["taxonomies"] == sorted({v.split("/")[0] for v in versions}), tag
        assert entry["custom"] == (1 in entry["custom_values"]), tag  # type: ignore[operator]


def test_leaf_tags_of_every_metric_are_in_the_evidence(catalog: Catalog) -> None:
    """Formula metrics have no tags of their own; the tags they actually read (through formula and
    fallback_formula, recursively) must all be evidenced, including for gross_margin and the
    gross_profit fallback."""
    evidence = load_evidence()
    for name in catalog:
        missing = leaf_tags(catalog, name) - set(evidence)
        assert not missing, f"{name} reads tags with no evidence: {sorted(missing)}"


# --- formulas --------------------------------------------------------------------------------


def test_formula_references_resolve_to_catalog_keys(catalog: Catalog) -> None:
    """formula and fallback_formula only name catalog keys (a typo like `revnue` would make the
    compiler fail at query time, not at load)."""
    for name, m in catalog.items():
        for expr in expressions(m):
            unknown = formula_refs(expr) - set(catalog)
            assert not unknown, f"{name}: {expr!r} references unknown {sorted(unknown)}"


def test_no_formula_cycles(catalog: Catalog) -> None:
    """Formulas form a DAG: load_catalog only rejects a metric naming itself, not a -> b -> a."""
    assert find_cycle(formula_graph(catalog)) is None


def test_cycle_detector_finds_cycles_and_accepts_dags() -> None:
    """Meta-test: the helper above must actually detect a cycle (else the test above is vacuous)."""
    cycle = find_cycle({"a": {"b"}, "b": {"c"}, "c": {"a"}})
    assert cycle is not None and cycle[0] == cycle[-1] and set(cycle) == {"a", "b", "c"}
    assert find_cycle({"a": {"a"}}) == ["a", "a"]
    assert find_cycle({"a": {"b", "c"}, "b": {"c"}, "c": set()}) is None


def test_formula_metrics_have_no_tags_and_tag_metrics_no_formula(catalog: Catalog) -> None:
    """Exactly one of tags/formula per metric (ADR-042 header). A formula metric reads tags only
    through its inputs, and a tag metric's only formula is its labelled `fallback_formula`."""
    for name, m in catalog.items():
        if m.formula is not None:
            assert m.tags is None, f"{name}: formula metric must not list tags"
            assert m.fallback_formula is None, f"{name}: formula metric cannot have a fallback"
        else:
            assert m.tags, f"{name}: a metric without a formula needs tags"


def test_every_fallback_formula_has_only_if_and_derived_label(catalog: Catalog) -> None:
    """ADR-042: a fallback_formula without `only_if` is never used, so it is dead config; and its
    result must be labelled `derived`, never presented as reported. Conditions are drawn from the
    known set and include the ones that keep a derived number honest."""
    for name, m in catalog.items():
        if m.fallback_formula is None:
            assert m.only_if is None and m.fallback_result is None, name
            continue
        assert m.only_if, f"{name}: fallback_formula without only_if is never used (ADR-042)"
        assert set(m.only_if) <= set(FALLBACK_CONDITIONS), name
        assert m.fallback_result == "derived", f"{name}: fallback must be labelled derived"
        assert {"same_entity", "same_period"} <= set(m.only_if), (
            f"{name}: a derived value must come from one entity and one period"
        )


# --- units -----------------------------------------------------------------------------------


def test_ratio_metrics_are_a_division_of_like_units(catalog: Catalog) -> None:
    """A `ratio` metric is a formula whose top-level operation is a division of two like-unit
    expressions (USD / USD). Anything else (a tag, a sum, USD / shares) would produce a number
    labelled ratio that is not one."""
    ratios = [n for n, m in catalog.items() if m.unit == "ratio"]
    assert ratios, "expected the margin metrics"
    for name in ratios:
        m = catalog[name]
        assert m.formula is not None and m.tags is None, f"{name}: ratio needs a formula"
        tree = ast.parse(m.formula, mode="eval").body
        assert isinstance(tree, ast.BinOp) and isinstance(tree.op, ast.Div), (
            f"{name}: a ratio's formula must be a division, got {m.formula!r}"
        )
        assert infer_unit(tree, catalog) == "ratio", name
        assert len(input_period_types(m.formula, catalog)) == 1, (
            f"{name}: numerator and denominator must share a period type"
        )


def test_formula_units_are_consistent_with_declared_unit(catalog: Catalog) -> None:
    """The unit inferred from every formula and fallback_formula equals the metric's declared
    unit, and the inputs share one period type with the result: no adding USD to shares, no
    subtracting an instant balance from a duration flow."""
    for name, m in catalog.items():
        for expr in expressions(m):
            tree = ast.parse(expr, mode="eval").body
            assert infer_unit(tree, catalog) == m.unit, f"{name}: {expr!r} is not {m.unit}"
        if m.fallback_formula is not None:
            periods = input_period_types(m.fallback_formula, catalog)
            assert periods == {m.period_type}, f"{name}: fallback mixes period types {periods}"
        if m.formula is not None:
            assert len(input_period_types(m.formula, catalog)) == 1, f"{name}: mixed periods"


def test_unit_matches_the_kind_of_tag(catalog: Catalog) -> None:
    """USD/shares metrics use per-share tags (EarningsPerShare*) and only they do; the `shares`
    metric uses a share-count tag; plain USD metrics use neither. A per-share tag under a USD
    metric would put 5.78 in a column the composer formats as billions."""
    for name, m in catalog.items():
        for tag in m.tags or []:
            per_share = tag.startswith("EarningsPerShare")
            share_count = "Shares" in tag
            if m.unit == "USD/shares":
                assert per_share, f"{name}: {tag} is not a per-share tag"
            elif m.unit == "shares":
                assert share_count and not per_share, f"{name}: {tag} is not a share-count tag"
            elif m.unit == "USD":
                assert not per_share and not share_count, f"{name}: {tag} is not a USD tag"
            else:
                pytest.fail(f"{name}: tag metric with unit {m.unit!r}")


def test_unit_checker_rejects_mixed_units(catalog: Catalog) -> None:
    """Meta-test: infer_unit must flag unit errors, or the consistency test proves nothing."""
    with pytest.raises(AssertionError):
        infer_unit(ast.parse("revenue + shares_outstanding", mode="eval").body, catalog)
    with pytest.raises(AssertionError):
        infer_unit(ast.parse("revenue / eps_basic", mode="eval").body, catalog)
    assert infer_unit(ast.parse("revenue - cost_of_revenue", mode="eval").body, catalog) == "USD"
    assert infer_unit(ast.parse("revenue / cost_of_revenue", mode="eval").body, catalog) == "ratio"


def test_duration_and_instant_tags_follow_the_statement(catalog: Catalog) -> None:
    """Balance-sheet quantities are instants and flows are durations: the period_type of the
    well-known balance-sheet metrics is `instant`, of income and cash-flow metrics `duration`.
    A flipped value would make the compiler look for the wrong period shape."""
    instants = {
        "total_assets",
        "total_liabilities",
        "stockholders_equity",
        "cash",
        "long_term_debt",
        "shares_outstanding",
    }
    for name, m in catalog.items():
        if m.tags is None:
            continue
        expected = "instant" if name in instants else "duration"
        assert m.period_type == expected, f"{name}: period_type {m.period_type}, want {expected}"


# --- presentation_basis (ADR-042) ------------------------------------------------------------


def test_presentation_basis_metrics_share_no_tag_with_any_other_metric(catalog: Catalog) -> None:
    """A metric with its own presentation basis (bank net revenue, revenue including assessed
    taxes) is a separate concept: its tag must not appear in another metric's chain, or the
    generic metric would silently fall back to a differently-based number (ADR-042)."""
    based = {n for n, m in catalog.items() if m.presentation_basis}
    assert based, "expected presentation_basis metrics (revenue_including_assessed_tax, bank)"
    for name in based:
        own = set(catalog[name].tags or [])
        for other, m in catalog.items():
            if other != name:
                shared = own & set(m.tags or [])
                assert not shared, f"{name} shares {sorted(shared)} with {other}"


def test_presentation_basis_metrics_are_never_formula_inputs(catalog: Catalog) -> None:
    """Nor may a formula or fallback_formula consume a presentation_basis metric: that is a
    fallback by another route (gross_margin on bank revenue would mix bases)."""
    based = {n for n, m in catalog.items() if m.presentation_basis}
    for name, refs in formula_graph(catalog).items():
        assert not (refs & based), f"{name} uses {sorted(refs & based)}"


def test_tags_are_not_listed_by_two_unrelated_metrics(catalog: Catalog) -> None:
    """A tag belongs to one concept: no tag may be a chain member of two metrics. (Stronger than
    the presentation_basis rule above; it holds for the current catalog and keeps the
    verification allowlist per concept unambiguous.)"""
    counts = Counter(tag for m in catalog.values() for tag in (m.tags or []))
    dupes = {t: c for t, c in counts.items() if c > 1}
    assert not dupes, f"tags in more than one metric: {dupes}"
